export const BODY: string = "\n<p>النص فوق صورة يفيد فقط إذا استطاع الناس قراءته. عنوان يختفي في سماء ساطعة أو تعليق يندمج في ظل داكن يفشل في عمله الوحيد.</p>\n<p>التباين هو ما يجعل النص مقروءًا. إنه فرق السطوع بين الحروف والخلفية خلفها، ويمكن إصلاحه في الصورة أو في النص أو في كليهما.</p>\n<p>يشرح هذا المقال كيف تبني ذلك التباين. يغطي التعتيم والتراكبات واللوحات واختيار الألوان وعادات الاختبار التي تكتشف النص غير المقروء قبل النشر.</p>\n<p>قبل النشر، يمكنك فحص تباين صورك مجانًا في المتصفح مع <a href=\"/ar/taadil-tabayun-as-sura/\">محرر تباين الصور</a> وضبط الصورة حتى يُقرأ النص بوضوح.</p>\n<h2 id=\"why-contrast-matters\">لماذا يهم التباين أكثر من الخط</h2>\n<p>خط جميل لا يستطيع أحد قراءته تصميم فاشل. أول عمل للنص فوق صورة هو أن يُقرأ، والتباين يقرر هل يتحقق ذلك العمل.</p>\n<p>معظم الصور تُرى على الهواتف في الخلاصات بأحجام صغيرة. نص واضح بالحجم الكامل على حاسوب قد يكون غير مقروء في معاينة خلاصة، حيث تقيس الصورة سنتيمترات قليلة. كما يؤثر التباين في الثقة: منشور بنص حاد وواضح يبدو احترافيًا.</p>\n<h2 id=\"text-vs-background\">النص أم الخلفية: العلاقة المركزية</h2>\n<p>المقروئية تولد من الفجوة بين سطوع النص وسطوع الخلفية. النص الأبيض فوق خلفية داكنة له فجوة كبيرة، والنص الأسود فوق خلفية فاتحة كذلك.</p>\n<p>المشكلة تأتي عندما تتغير الخلفية خلف السطر نفسه. تعليق يبدأ فوق ظل داكن وينتهي فوق سماء ساطعة سيكون مقروءًا في طرف وغير مرئي في الطرف الآخر. وراجع التباين في السطر كله لا في نقطة واحدة، فكل كلمة يجب أن تُقرأ.</p>\n<h2 id=\"choosing-text-colour\">كيف تختار لون نص للتباين</h2>\n<p>الأبيض هو اللون الآمن للنص فوق الصور، لأن معظم الصور فيها مناطق داكنة كافية ليُقرأ، وحد داكن يجعله يعمل فوق المناطق الفاتحة أيضًا.</p>\n<p>الأسود يعمل جيدًا في الصور الفاتحة والهوائية، مثل الشواطئ ومشاهد الثلج والجدران البيضاء. ويفشل في الصور الداكنة حيث يختفي في الظلال. والألوان الساطعة مثل الأصفر أو السماوي قد تعمل للعناوين القصيرة، لكنها أصعب قراءة في التعليقات الطويلة.</p>\n<h2 id=\"darkening-photo\">كيف تعتّم الصورة خلف النص</h2>\n<p>تعتيم الصورة كلها هو أبسط طريقة لجعل النص الأبيض مقروءًا. خفض سطوع 20 إلى 30 بالمئة ينشئ منطقة داكنة تبرز عليها الحروف البيضاء.</p>\n<p>استخدم <a href=\"/ar/taadil-sutoo-as-sura/\">محرر سطوع الصورة</a> لتعتيم الصورة قبل إضافة النص. الصورة الأظلم تعطي الحروف خلفية واضحة دون إخفاء الصورة تمامًا. وراجع الصورة بعد التعتيم: يجب أن تبقى معروفة كالصورة نفسها، فقط أكثر ظلمة، مع بقاء الموضوع ظاهرًا والنص مقروءًا بوضوح.</p>\n<h2 id=\"lightening-photo\">كيف تفتّح الصورة خلف النص الداكن</h2>\n<p>التفتيح يعمل بالعكس نفسه. زيادة سطوع خلف النص الأسود تنشئ منطقة فاتحة تبرز عليها الحروف الداكنة.</p>\n<p>هذا يناسب الصور الفاتحة والهوائية، حيث يجب أن يبدو النص خفيفًا ونظيفًا. جدار أبيض أو سماء شاحبة، مفتّحة أكثر، تعطي النص الأسود خلفية مثالية. واحذر الأضواء عند التفتيح: سماء فاتحة أصلًا قد تحترق إلى أبيض نقي، وهذا مقبول خلف النص لكنه يبدو غريبًا في بقية الصورة.</p>\n<h2 id=\"overlays-and-panels\">التراكبات ولوحات الخلفية</h2>\n<p>التراكب طبقة شبه شفافة توضع فوق الصورة كلها. التراكب الداكن يجعل النص الأبيض مقروءًا في كل مكان، بينما تبقى الصورة ظاهرة من خلاله.</p>\n<p>أما اللوحة فنسخة أصغر من الفكرة نفسها: صندوق شبه شفاف يوضع خلف النص فقط. اللوحة الداكنة تجعل النص الأبيض مقروءًا، والفاتحة تفعل الشيء نفسه للنص الداكن. واللوحات هي حل المقروئية الأكثر موثوقية، لأنها تنشئ خلفية متسقة لا تستطيع الصورة تقديمها.</p>\n<h2 id=\"contrast-for-headlines\">التباين للعناوين</h2>\n<p>العناوين تحتاج أقوى تباين، لأنها أول ما تلتقطه العين. عنوان صعب القراءة يجعل المشاهد يتخطى الصورة كلها.</p>\n<p>استخدم نصًا كبيرًا وعريضًا بفجوة لون قوية. الحروف البيضاء العريضة فوق صورة معتمة، أو الحروف السوداء العريضة فوق صورة فاتحة، هما التركيبتان الكلاسيكيتان. وأضف حدًا أو ظلًا للعنوان عندما تتغير الخلفية، فالتأثير ينشئ منطقة تباين محلية حول كل حرف.</p>\n<h2 id=\"contrast-for-captions\">التباين للتعليقات والنص الصغير</h2>\n<p>التعليقات والنص الصغير تحتاج عناية أكثر من العناوين، لأن الحروف الصغيرة أصعب قراءة. تعليق بتباين ضعيف غير مرئي في معاينة خلاصة.</p>\n<p>استخدم لوحة خلف النص الصغير. تعليق فوق صورة مزدحمة يحتاج الخلفية المتسقة التي لا تستطيع إلا لوحة تقديمها، لأن الحدود وحدها قد لا تكفي. وأبقِ التعليقات قصيرة: كلمات قليلة بتباين قوي تعمل أفضل بكثير من جملة طويلة بتباين ضعيف.</p>\n<h2 id=\"testing-readability\">كيف تختبر المقروئية قبل النشر</h2>\n<p>اختبر النص على هاتف في خلاصة بالحجم الذي سيُعرض به. صدّر الصورة وافتحها على هاتفك وراجع هل تُقرأ الكلمات دون تكبير.</p>\n<p>وراجع الصورة أيضًا بإضاءة مختلفة. شاشة هاتف تحت شمس ساطعة تغسل النص الباهت، فتعليق مقروء في الداخل قد يفشل في الخارج. واطلب من شخص آخر قراءته: عينان جديدتان تكتشفان النص غير المقروء أسرع بكثير من الشخص الذي صنعه.</p>\n<h2 id=\"contrast-for-social\">التباين للنص على وسائل التواصل</h2>\n<p>خلاصات التواصل مزدحمة وسريعة، ويجب أن يُقرأ النص بنظرة واحدة. منشور بتباين ضعيف يُمرَّر، بينما منشور بتباين قوي يوقف التمرير.</p>\n<p>أبقِ النص الاجتماعي كبيرًا وعالي التباين. العناوين تحتاج حجمًا قرب قمة النطاق، بفجوة لون قوية مع الصورة خلفها. وتذكر أن منصات التواصل تضغط صورك: تعليق باهت قد يصبح غير مرئي بعد الضغط، فاختبر النص في نسخة منزّلة من المنشور.</p>\n<h2 id=\"contrast-for-slides\">التباين للشرائح والعروض</h2>\n<p>الشرائح تُرى من بعيد، فيحتاج النص تباينًا قويًا جدًا. عنوان مقروء على حاسوب محمول قد يكون غير مرئي من آخر قاعة.</p>\n<p>عتّم الصورة خلف نص الشريحة بسخاء. خفض سطوع 30 بالمئة أو أكثر يعطي النص الأبيض خلفية واضحة، حتى على شاشة عرض كبيرة. واستخدم نصًا كبيرًا وعريضًا للشرائح، فالعنوان يجب أن يُقرأ من الصف الأخير. واختبر الشريحة على جهاز العرض الحقيقي إن استطعت.</p>\n<h2 id=\"accessibility\">سهولة الوصول: تباين يستطيع الجميع قراءته</h2>\n<p>التباين الجيد يساعد الجميع، لكنه يهم أكثر للأشخاص ضعاف البصر. التباين العالي والحجم الكبير والخلفية البسيطة تجعل النص مقروءًا لكثير من الناس.</p>\n<p>تجنب الاعتماد على اللون وحده لنقل المعنى. كلمة حمراء وكلمة خضراء قد تبدوان متطابقتين لشخص مصاب بعمى الألوان، فاستخدم الحجم أو الوزن أيضًا. وأبقِ النص قصيرًا واللغة بسيطة، وأضف نصًا بديلًا عند مشاركة الصورة.</p>\n<h2 id=\"common-mistakes\">الأخطاء الشائعة في التباين</h2>\n<p>الخطأ الأكثر شيوعًا هو نص أبيض فوق صورة فاتحة، دون حد أو ظل أو لوحة. الحروف تضيع في السماء، والمشاهد يرى الصورة فقط.</p>\n<p>من الأخطاء الأخرى وضع نص فوق وجه أو نمط مزدحم. العين لا تستطيع فصل الحروف عن القوام تحتها، وتصبح الكلمات صعبة المتابعة. والناس يستخدمون أيضًا ألوانًا كثيرة جدًا: ثلاثة أو أربعة ألوان نص في صورة تبدو فوضوية، بينما لون متسق بتباين قوي يبقي التصميم نظيفًا.</p>\n<h2 id=\"contrast-and-filters\">التباين والفلاتر والنص معًا</h2>\n<p>الفلاتر تغيّر تباين الصورة، ما يؤثر في النص فوقها. فلتر عالي التباين قد يجعل الخلفية أكثر ازدحامًا، ما يضر بالمقروئية.</p>\n<p>طبّق الفلتر أولًا ثم راجع تباين النص. فلتر يعتّم الصورة قد يحسّن النص الأبيض، بينما فلتر يفتّحها قد يفسد النص نفسه. وللرسوم ذات النص الكثيف، استخدم فلترًا ناعمًا أو لا شيء. وعندما يجب أن يتعايش فلتر ونص، أضف لوحة خلف النص.</p>\n<h2 id=\"before-after-examples\">قبل وبعد: كيف يبدو التباين الجيد</h2>\n<p>صورة بنص أبيض فوق سماء ساطعة ودون حد هي الفشل الكلاسيكي. الكلمات غير مرئية، والمشاهد يرى الصورة فقط.</p>\n<p>نفس الصورة بتراكب داكن تصبح مقروءة فورًا. السماء تعتّم والحروف البيضاء تبرز وتبقى الصورة ظاهرة من خلال التراكب. وتعليق فوق حشد مزدحم بلوحة خلفه هو الحل الموثوق: اللوحة تنشئ منطقة نظيفة، والكلمات تُقرأ دون إخفاء الصورة كلها.</p>\n<h2 id=\"readability-checklist\">قائمة مقروئية قبل النشر</h2>\n<p>راجع التباين في سطر النص كله. كل كلمة يجب أن تُقرأ لا الأولى فقط، ويجب ألا تتغير الخلفية تحت السطر.</p>\n<p>راجع الحجم على هاتف في معاينة خلاصة. إذا كانت الكلمات صعبة القراءة دون تكبير، كبّر الحجم أو قصّر النص. وراجع النص تحت ضوء الشمس الساطع، وراجع الموضع: يجب أن يكون النص فوق منطقة ناعمة، بعيدًا عن الوجوه والحواف، بمساحة كافية حوله للتنفس.</p>\n<p>للخطوات العملية، راجع <a href=\"/ar/blog/kayfiyya-taadil-tabayun-as-sura/\">كيف تضبط تباين صورة</a> و<a href=\"/ar/blog/kayfiyya-idafa-nass-ila-as-sura/\">كيف تضيف نصًا إلى صورة</a>. وللأدلة الكاملة، اقرأ <a href=\"/ar/blog/dalil-muharrir-tabayun-as-suwar/\">محرر تباين الصور: الدليل الكامل</a> و<a href=\"/ar/blog/nasaih-li-qiraat-an-nass-ala-as-suwar/\">النص على الصور: الخطوط والتباين والمقروئية</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أجعل النص الأبيض مقروءًا فوق صورة فاتحة؟","answer":"عتّم الصورة خلف النص، أو أضف حدًا داكنًا أو ظلًا حول الحروف، أو ضع لوحة داكنة شبه شفافة خلف الكلمات. خفض سطوع 20 إلى 30 بالمئة يكفي عادة لجعل النص الأبيض يبرز."},{"question":"هل أعتّم الصورة كلها أم المنطقة خلف النص فقط؟","answer":"تعتيم الصورة كلها أبسط ويناسب الشرائح والملصقات. اللوحة أو التراكب خلف النص فقط أفضل عندما يجب أن يبقى بقية الصورة فاتحًا. الخياران يعملان؛ اختر حسب ما يجب أن يبقى ظاهرًا."},{"question":"أي مستوى تباين أحتاج للنص فوق صورة؟","answer":"أكبر ما تستطيع تحقيقه. النص الأبيض فوق خلفية داكنة والنص الأسود فوق خلفية فاتحة هما التركيبتان الموثوقتان. وراجع السطر كله، لأن خلفية متغيرة تحت النص قد تجعل جزءًا منه غير مقروء."},{"question":"لماذا يبدو نصي جيدًا على حاسوبي لكنه غير مقروء على هاتفي؟","answer":"الهاتف يعرض الصورة أصغر بكثير، خصوصًا في معاينة خلاصة، والنص الصغير ذو التباين الضعيف يختفي عند ذلك الحجم. اختبر الصورة على هاتفك بحجم الخلاصة، وكبّر الحجم أو قصّر النص."},{"question":"هل يؤثر الفلتر في مقروئية النص فوق صورة؟","answer":"نعم، الفلاتر تغيّر تباين الصورة وسطوعها، ما يغيّر الخلفية التي يستند إليها النص. طبّق الفلتر أولًا ثم راجع تباين النص. وأضف لوحة خلف النص إذا أزال الفلتر الخلفية المتسقة."},{"question":"كيف أختبر تباين النص قبل النشر؟","answer":"اعرض الصورة على هاتفك بحجم الخلاصة، وراجعها تحت ضوء الشمس الساطع، وضيّق عينيك: إذا بقي النص ظاهرًا وأنت تضيق عينيك، فالتباين قوي بما يكفي. واطلب أيضًا من شخص آخر قراءته."}];
